"use strict";exports.id=793,exports.ids=[793],exports.modules={4793:(a,b,c)=>{c.d(b,{$6:()=>f,Ks:()=>g,QA:()=>h,WB:()=>e,yv:()=>i});let d={tx_count_daily:{key:"tx_count_daily",label:"Daily transactions",shortLabel:"Transactions",unit:"count",format:"int",category:"Core Activity",doc:{what:{basic:"Counts how many transactions were recorded that day.",advanced:"Daily transaction count for the chain (unit: transactions/day)."},how:{basic:"Read as a single numeric value from the published daily gold file for each date.",advanced:"Gold field: tx_count_daily from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. The UI contextualizes the raw series with MA7/MA30 (from derived where available, otherwise computed as a trailing average over available days)."},why:{basic:"It is a direct, price-agnostic proxy for day-to-day network usage.",advanced:"Transaction count is a core demand/activity proxy. Interpretation should rely on smoothed trends (MA7/MA30) and explicit coverage/freshness rather than single-day spikes."},value:{basic:"Helps you see whether activity is low/typical/elevated versus the chain’s own recent history.",advanced:"Supports regime/context reading: sustained deviations from baseline are more informative than isolated peaks. Use alongside fees/utilization to distinguish demand from subsidized or low-cost activity."}},methodology:{definition:"Number of transactions recorded on-chain for the date (calendar day, UTC).",computation:"Directly read from the pipeline’s gold daily output. No interpolation is applied; missing days remain missing and are reported via manifest-driven coverage.",caveats:["Missing days in manifest indicate missing data, not zero activity.","Cross-chain comparisons are not normalized; interpret within-chain unless you explicitly normalize."]},availabilityByChain:{bitcoin:{kind:"available"},ethereum:{kind:"available"},arbitrum:{kind:"possible_missing",reason_basic:"Occasional gaps can occur due to rollup indexing lag.",reason_advanced:"Nulls typically indicate upstream rollup indexing lag or incomplete coverage rather than zero activity; interpret with coverage/confidence."},base:{kind:"possible_missing",reason_basic:"Occasional gaps can occur due to rollup indexing lag.",reason_advanced:"Nulls typically indicate upstream indexing lag/incomplete coverage rather than zero activity; interpret with coverage/confidence."}},anchors:{methodology:"/methodology#tx_count_daily",wiki:"/wiki#tx_count_daily"}},unique_active_addresses:{key:"unique_active_addresses",label:"Active addresses",shortLabel:"Active addresses",unit:"count",format:"int",category:"Core Activity",doc:{what:{basic:"Counts how many unique addresses were active that day (sent or received a transaction).",advanced:"Unique active addresses per day (unit: addresses/day), as defined by the pipeline’s address-activity logic."},how:{basic:"Computed by the pipeline and written as a daily gold numeric field.",advanced:"Gold field: unique_active_addresses from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. Exact activity definition can vary by chain data model (e.g., UTXO vs account-based); see methodology caveats."},why:{basic:"It approximates participation breadth rather than raw throughput.",advanced:"Transaction count can rise due to batching or spam; unique actives helps contextualize whether activity is broad-based or concentrated."},value:{basic:"Helps distinguish broad participation from activity driven by a small number of entities.",advanced:"Useful for regime/context reading: a rising tx_count_daily with flat unique_active_addresses can indicate concentration, batching, or repeated interactions by fewer entities."}},methodology:{definition:"Count of distinct addresses observed as active on the date (UTC).",computation:"Pipeline-derived per chain from observed transaction participants; emitted as a daily gold numeric. No interpolation; missing days remain missing.",caveats:["Address semantics differ by chain (e.g., UTXO scripts vs accounts).","One entity can control many addresses; interpret as an activity proxy, not a user count."]},availabilityByChain:{bitcoin:{kind:"possible_missing",reason_basic:"Address activity derivation can lag depending on upstream parsing.",reason_advanced:"If upstream address parsing is incomplete for a date, this field may be null; treat as missing coverage, not zero."},ethereum:{kind:"available"},arbitrum:{kind:"possible_missing",reason_basic:"Rollup indexing lag can create gaps.",reason_advanced:"Nulls usually indicate indexing lag/incomplete address extraction rather than no activity."},base:{kind:"possible_missing",reason_basic:"Rollup indexing lag can create gaps.",reason_advanced:"Nulls usually indicate indexing lag/incomplete address extraction rather than no activity."}},anchors:{methodology:"/methodology#unique_active_addresses",wiki:"/wiki#unique_active_addresses"}},median_tx_fee_native:{key:"median_tx_fee_native",label:"Median transaction fee (native)",shortLabel:"Median fee",unit:"native",format:"float",category:"Execution & Cost",doc:{what:{basic:"The median fee paid per transaction that day, denominated in the chain’s native token.",advanced:"Median per-transaction fee in native units (median across transactions observed on the date)."},how:{basic:"Computed by the pipeline from per-transaction fee data, then summarized as a daily median.",advanced:"Gold field: median_tx_fee_native from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. Fee definition follows chain conventions (e.g., gas_used * effective_gas_price for EVM chains, fee components for BTC)."},why:{basic:"It describes fee pressure and competition for limited capacity without using price.",advanced:"A descriptive friction signal: higher typical fees often co-occur with congestion or higher willingness-to-pay for inclusion, but does not imply value judgment."},value:{basic:"Shows whether typical transaction costs are low/typical/elevated versus recent history.",advanced:"Helps contextualize activity: rising transactions with rising median fee suggests capacity pressure; rising transactions with flat/low fees suggests slack capacity or subsidized usage."}},methodology:{definition:"Median fee paid per transaction on the date, denominated in native token units.",computation:"Pipeline computes per-transaction fees using chain-specific fee rules, then takes the median over transactions for the date. No interpolation is applied.",caveats:["Native-unit fees are not directly comparable across chains without additional normalization.","Some chains have fee mechanisms that change over time (upgrades); treat long histories with caution."]},availabilityByChain:{bitcoin:{kind:"available"},ethereum:{kind:"available"},arbitrum:{kind:"available"},base:{kind:"available"}},anchors:{methodology:"/methodology#median_tx_fee_native",wiki:"/wiki#median_tx_fee_native"}},gas_utilization_pct:{key:"gas_utilization_pct",label:"Gas utilization",shortLabel:"Gas utilization",unit:"percent",format:"pct",category:"Execution & Cost",doc:{what:{basic:"How full blocks were on average that day, expressed as a percent of capacity.",advanced:"Daily average of gas_used / gas_limit (or equivalent capacity metric), expressed as percent."},how:{basic:"Computed from block-level utilization and aggregated to a daily average by the pipeline.",advanced:"Gold field: gas_utilization_pct from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. For non-EVM chains this metric may be structurally not applicable and is expected to be null."},why:{basic:"It is a descriptive capacity-pressure signal.",advanced:"Utilization helps interpret fee and activity trends: high utilization indicates blocks are near capacity; low utilization indicates slack."},value:{basic:"Helps you understand whether the chain was capacity-constrained over the period.",advanced:"Pairs with fee and transaction trends to distinguish demand spikes from capacity expansion or slack regimes. Useful for regime context without any price signal."}},methodology:{definition:"Daily average capacity utilization expressed as percent.",computation:"Per block utilization is computed (gas_used / gas_limit) then aggregated to a daily average and expressed as percent.",caveats:["Structural NA for non-EVM chains where gas concepts do not exist.","Protocol upgrades can change effective limits; interpret long histories with that in mind."]},availabilityByChain:{bitcoin:{kind:"expected_na",reason_basic:"Bitcoin does not use a gas model, so gas utilization is not applicable.",reason_advanced:"The gas construct is EVM-specific; Bitcoin capacity is better described via block size/weight and fee market metrics."},ethereum:{kind:"available"},arbitrum:{kind:"available"},base:{kind:"available"}},anchors:{methodology:"/methodology#gas_utilization_pct",wiki:"/wiki#gas_utilization_pct"}},failed_tx_rate:{key:"failed_tx_rate",label:"Failed transaction rate",shortLabel:"Failure rate",unit:"ratio",format:"pct",category:"Execution & Cost",doc:{what:{basic:"The share of transactions that failed that day (as a percent).",advanced:"Daily failure ratio (failed / total) expressed as percent, based on chain-specific failure semantics."},how:{basic:"Computed by the pipeline from transaction status outcomes, then aggregated daily.",advanced:"Gold field: failed_tx_rate from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. For chains where failure semantics are not available or not meaningful, the metric may be null."},why:{basic:"It describes execution friction and potential UX degradation without implying blame.",advanced:"Failure rate helps interpret demand: high activity with elevated failures can indicate congestion, mispriced fees, or application-level issues."},value:{basic:"Helps you see whether execution was smooth or error-prone versus recent history.",advanced:"Useful as an operational context signal: persistent increases can coincide with congestion regimes or ecosystem events (without implying causality)."}},methodology:{definition:"Daily percentage of transactions that are classified as failed.",computation:"Pipeline counts failed vs total transactions for the date and computes the ratio. No interpolation; missing days remain missing.",caveats:["Failure semantics can vary by chain and data source.","Some failures are user-initiated reverts; interpret as friction, not necessarily network fault."]},availabilityByChain:{bitcoin:{kind:"expected_na",reason_basic:"Bitcoin does not expose an EVM-style transaction success/failure status.",reason_advanced:"UTXO validation differs from execution traces; failure classification is not directly comparable to EVM reverts."},ethereum:{kind:"available"},arbitrum:{kind:"available"},base:{kind:"available"}},anchors:{methodology:"/methodology#failed_tx_rate",wiki:"/wiki#failed_tx_rate"}},avg_block_time_sec:{key:"avg_block_time_sec",label:"Average block time (seconds)",shortLabel:"Block time",unit:"seconds",format:"float",category:"Reliability",doc:{what:{basic:"Average time between blocks that day (in seconds).",advanced:"Daily average block interval (seconds) based on observed block timestamps."},how:{basic:"Computed by the pipeline from consecutive block timestamps and averaged daily.",advanced:"Gold field: avg_block_time_sec from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. Interpretation differs by chain (e.g., PoW variance vs fixed-slot systems)."},why:{basic:"It is an operational stability indicator.",advanced:"Block time captures production cadence. Persistent deviations can indicate operational or protocol-level conditions, without implying causality."},value:{basic:"Helps you see whether block production was stable versus recent history.",advanced:"Useful for context: changing cadence affects throughput and user experience. Combine with block_count and activity for a fuller picture."}},methodology:{definition:"Average time between consecutive blocks for the date (seconds).",computation:"Compute time deltas between consecutive blocks and average over blocks in the UTC day. No interpolation; missing days remain missing.",caveats:["Timestamp granularity and consensus design affect variance; interpret within-chain.","Some rollups/sequencers may show different cadence semantics than L1 block production."]},availabilityByChain:{bitcoin:{kind:"available"},ethereum:{kind:"available"},arbitrum:{kind:"available"},base:{kind:"available"}},anchors:{methodology:"/methodology#avg_block_time_sec",wiki:"/wiki#avg_block_time_sec"}},block_count_daily:{key:"block_count_daily",label:"Blocks per day",shortLabel:"Blocks/day",unit:"count",format:"int",category:"Reliability",doc:{what:{basic:"Counts how many blocks were produced that day.",advanced:"Daily block count (unit: blocks/day) from observed on-chain block production."},how:{basic:"Read from the pipeline’s gold daily output as a single numeric value per date.",advanced:"Gold field: block_count_daily from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. Closely related to avg_block_time_sec but more robust to outliers in time deltas."},why:{basic:"It describes production output and operational regularity.",advanced:"Block count is a stability/throughput context metric and is often easier to interpret than raw timestamp variance."},value:{basic:"Helps you detect days/weeks with unusual production output.",advanced:"Useful for regime context: persistent deviations can co-occur with outages, reorganizations, or design changes, without implying causality."}},methodology:{definition:"Number of blocks produced on the date (UTC).",computation:"Directly counted from blocks observed in the pipeline and emitted as a gold daily numeric field.",caveats:["Some chains have variable block cadence; interpret within-chain.","Missing days in manifest indicate missing coverage, not zero blocks."]},availabilityByChain:{bitcoin:{kind:"available"},ethereum:{kind:"available"},arbitrum:{kind:"available"},base:{kind:"available"}},anchors:{methodology:"/methodology#block_count_daily",wiki:"/wiki#block_count_daily"}},value_transferred_native:{key:"value_transferred_native",label:"Value transferred (native)",shortLabel:"Value transferred",unit:"native",format:"float",category:"Value / Throughput",doc:{what:{basic:"Total amount of the native token transferred on-chain that day.",advanced:"Daily sum of native token value transferred (native units/day), as computed by the pipeline."},how:{basic:"Computed by the pipeline as a daily aggregate of transfers and written to the gold file.",advanced:"Gold field: value_transferred_native from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. Transfer accounting is chain-specific (e.g., UTXO outputs vs account transfers); see caveats."},why:{basic:"It provides an economic-throughput proxy without using any price data.",advanced:"Value transferred complements activity metrics: high activity can be spammy; value transferred can indicate economic weight, still price-agnostic."},value:{basic:"Helps you see whether activity is associated with larger settlement flows or mostly small transfers.",advanced:"Supports context reading: divergence between tx_count and value_transferred can indicate changes in typical transfer size or usage mix, without implying motives."}},methodology:{definition:"Daily aggregate of transferred native token amount (native units).",computation:"Pipeline sums native transfer amounts over the UTC day using chain-specific transfer extraction logic, then emits the daily total.",caveats:["Transfer extraction differs across chain data models; comparisons require care.","Large internal movements can dominate totals; interpret with median_tx_value_native where available."]},availabilityByChain:{bitcoin:{kind:"available"},ethereum:{kind:"available"},arbitrum:{kind:"available"},base:{kind:"available"}},anchors:{methodology:"/methodology#value_transferred_native",wiki:"/wiki#value_transferred_native"}},median_tx_value_native:{key:"median_tx_value_native",label:"Median transaction value (native)",shortLabel:"Median value",unit:"native",format:"float",category:"Value / Throughput",doc:{what:{basic:"Median value transferred per transaction that day, denominated in the chain’s native token.",advanced:"Median per-transaction transferred value in native units (median across transactions observed on the date)."},how:{basic:"Computed by the pipeline from per-transaction transferred value and summarized as a daily median.",advanced:"Gold field: median_tx_value_native from public/data/published/v1/gold/<chain>/YYYY-MM-DD.json. Exact definition depends on how transfers are extracted per chain (UTXO vs account-based)."},why:{basic:"It adds context to activity and total value transferred.",advanced:"Median transfer size helps interpret whether changes in total value are broad-based or dominated by a small number of large transfers."},value:{basic:"Helps you see whether typical transfers are small/typical/large versus recent history.",advanced:"Use with tx_count and value_transferred: rising total value with stable tx_count can indicate larger typical transfers; rising tx_count with falling median value can indicate smaller typical transfers."}},methodology:{definition:"Median transferred native value per transaction on the date.",computation:"Pipeline computes per-transaction transferred amount, then takes the median over transactions for the UTC day.",caveats:["Transfer extraction differs across chains; interpret within-chain unless normalized and carefully defined.","Medians reduce outlier sensitivity but still depend on transfer extraction rules."]},availabilityByChain:{bitcoin:{kind:"possible_missing",reason_basic:"Median value may be unavailable depending on transfer parsing coverage.",reason_advanced:"If upstream transfer parsing is incomplete for a date, this field may be null; treat as missing coverage."},ethereum:{kind:"available"},arbitrum:{kind:"available"},base:{kind:"available"}},anchors:{methodology:"/methodology#median_tx_value_native",wiki:"/wiki#median_tx_value_native"}}},e=Object.keys(d);function f(a){return d[a]??null}function g(a){let b=f(a);if(!b)throw Error(`Unknown metric key: ${a}`);return b}function h(a){let b=g(a);return{methodologyHref:b.anchors.methodology,wikiHref:b.anchors.wiki}}function i(a,b){return g(b).availabilityByChain[a]??{kind:"available"}}}};